// ClickUp list statuses are the funnel. One mapping, kept in code so the dashboard never drifts.
const MAP = {
  'qualified': 'qualified',
  'discovery call booked': 'discovery_call_set',
  'discovery call done': 'discovery_call_attended',
  'ambition interview done': 'ambition_interview_done',
  'architect session done': 'architect_session_done',
  'won': 'converted',
  'lost': 'dropped',
};
return $input.all().flatMap(item => {
  const b = item.json;
  const status = (b.history_items?.[0]?.after?.status || b.status?.status || '').toLowerCase();
  const stage = MAP[status];
  if (!stage) return [];                       // ignore statuses outside the funnel
  return [{ json: {
    event_id: `${b.task_id}-${b.history_items?.[0]?.id || Date.now()}`,
    lead_id: b.task_id,
    stage,
    occurred_at: new Date(Number(b.history_items?.[0]?.date || Date.now())).toISOString(),
    note: b.history_items?.[0]?.comment?.text_content || null,
  }}];
});

