VALUES ('{{$json.event_id}}', '{{$json.lead_id}}', '{{$json.stage}}', '{{$json.occurred_at}}', {{ $json.note ? "'" + $json.note.replace(/'/g, "''") + "'" : 'NULL' }})
ON CONFLICT (event_id) DO NOTHING;
